effect.shader:
void main(){
vec2 fragCoord = acScreenNorm * acScreenSize;
vec2 iResolution = acScreenSize;
float iTime = acTime * speed;
vec2 uv = (2.0 * fragCoord - iResolution.xy) / max(iResolution.x, iResolution.y);
for (float i = 1.0; i < 10.0; i += 1.0) {
uv.x += amount / i * cos(i * freqX * uv.y + iTime);
uv.y += amount / i * cos(i * freqY * uv.x + iTime);
}
vec3 col = vec3(base) / max(abs(sin(iTime - uv.y - uv.x)), 1e-4);
vec4 gen = vec4(col, 1.0);
vec4 baseCol = texture2DCv(inputImg.texture, acScreenNorm);
vec4 outC = gen * opacity;
outC = baseCol * (1.0 - outC.a) + outC;
gl_FragColor = outC;
}
